def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    baby_patches = image_patch.find("baby")
    toy_patches = image_patch.find("toy")

    if not baby_patches:
        return image_patch

    if not toy_patches:
        return baby_patches[0]

    closest_toy = None
    min_distance = float('inf')

    for baby in baby_patches:
        baby_center_x = (baby.left + baby.right) / 2
        baby_center_y = (baby.lower + baby.upper) / 2

        for toy in toy_patches:
            toy_center_x = (toy.left + toy.right) / 2
            toy_center_y = (toy.lower + toy.upper) / 2

            dist = math.sqrt((baby_center_x - toy_center_x) ** 2 + (baby_center_y - toy_center_y) ** 2)

            if dist < min_distance:
                min_distance = dist
                closest_toy = toy

    if closest_toy:
        return closest_toy

    return baby_patches[0]

